import{_ as l,l as s,o as e,c as i,v as o,p as d,x as t,d as n,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Dolev–Yao","description":"","frontmatter":{"title":"Dolev–Yao","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dolev-yao.md","filePath":"cs/dolev-yao.md","lastUpdated":1789023840000}'),h={name:"cs/dolev-yao.md"};function p(_,a,D,m,B,A){const r=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="dolev–yao" tabindex="-1">Dolev–Yao <a class="header-anchor" href="#dolev–yao" aria-label="Permalink to &quot;Dolev–Yao&quot;">​</a></h1><div class="epigraph"><p>网络敌手可以拆、拼、重放它看见的项，但不能从密文算出明文，除非它有密钥——协议在这个代数里证明安全或不安全。</p><footer>—— Dolev and Yao, On the Security of Public Key Protocols, IEEE TIT 1983；Anderson 对协议假设的整理</footer></div><p><a href="/cs/stride">上一课</a>用清单问数据流图。本课不重列六类。缺口是协议课的敌手：不是「黑客」口号，而是形式化能力。Dolev–Yao：控制信道，任意组合已知消息，密码原语当黑盒。后课对称加密在此模型里才有「够用的那一层」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>STRIDE 的「篡改/伪造」在网上太宽。Needham–Schroeder 一类协议要问：在能改包的敌手下，认证还是否成立。Dolev–Yao 把加密当成理想锁：没有钥匙打不开，有钥匙可以构造新项。缺口是<strong>协议分析的默认敌手</strong>，不是某一分组算法。</p><p><span class="marginnote">计算模型（概率多项式时间）更细，后课只在需要时点名。侧信道不在 DY 里，后课瞬态执行再扩展模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>消息是项：原子、对、加密。敌手封闭于投影、配对、用已知键加解密、重放。协议是角色进程。安全目标写成「敌手项集里不出现某秘密」或「会话绑定到声称身份」。本课不跑具体攻击轨迹。</p>',8)),(e(),d(c,null,{default:t(()=>[E(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E4%BF%A1%E9%81%93%E7%94%B1%E6%95%8C%E6%89%8B%E4%B8%AD%E7%BB%A7%22%5D%20--%3E%20DY%5B%22%E6%8B%86%E5%88%86%20%2F%20%E9%85%8D%E5%AF%B9%20%2F%20%E9%87%8D%E6%94%BE%22%5D%0A%20%20DY%20--%3E%20BOX%5B%22%E6%97%A0%E5%AF%86%E9%92%A5%E4%B8%8D%E8%83%BD%E5%BC%80%E5%AF%86%E6%96%87%22%5D%0A%20%20BOX%20--%3E%20GOAL%5B%22%E7%A7%98%E5%AF%86%E4%B8%8D%E5%87%BA%E7%8E%B0%E5%9C%A8%E6%95%8C%E6%89%8B%E9%A1%B9%E9%9B%86%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把敌手钉成代数，后课 TLS、Kerberos 才能说「防的是 DY 主动者，不防已泄露的私钥」。Kerckhoffs 已在威胁模型课：算法公开。DY 再加：算法理想。真实分组模式若误用，会漏出 DY 假定锁不住的性质——下一单元对称加密与模式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把模型检测工具当必会软件。共享密钥下明文如何藏进密文，下一课对称加密。</p><p>后课默认：协议敌手是 DY 主动者。对称密码服务「无密钥则不可读」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Dolev–Yao：控制网络，密码当理想锁。</li><li>不覆盖侧信道与弱随机数。</li><li>对称加密下一课。</li><li>出处：Dolev and Yao, <em>IEEE TIT</em> 1983；Anderson。</li></ul>',7))])}const v=l(h,[["render",p]]);export{f as __pageData,v as default};
